def bisection_method(f, a, b, tol=1e-5, max_iter=100):
    for i in range(max_iter):
        c = (a + b) / 2
        if f(c) == 0 or (b - a) / 2 < tol:
            return c
        elif f(a) * f(c) < 0:
            b = c
        else:
            a = c
    return (a + b) / 2

def f(x):
    return x**2 - 2
print(bisection_method(f, 0, 2))

