def find_next_term(series):
    diff = series[1] - series[0]
    return series[-1] + diff

def pattern_recognition(sequence):
    # Identify the pattern type
    if sequence[1] - sequence[0] == sequence[2] - sequence[1]:
        return 'arithmetic'
    elif sequence[1] / sequence[0] == sequence[2] / sequence[1]:
        return 'geometric'
    else:
        return 'unknown'

